$ErrorActionPreference='Stop'
$Root=Split-Path -Parent $MyInvocation.MyCommand.Path
Set-Location $Root
Write-Host 'N-MEGA3 dosyalari uygulanıyor...' -ForegroundColor Cyan
New-Item -ItemType Directory -Force -Path (Join-Path $Root 'scripts') | Out-Null
New-Item -ItemType Directory -Force -Path (Join-Path $Root 'src\certification\player-readiness') | Out-Null
[IO.File]::WriteAllBytes((Join-Path $Root 'scripts\n-mega3-2024-builder-progression-audit.mjs'),[Convert]::FromBase64String(''))
[IO.File]::WriteAllBytes((Join-Path $Root 'src\certification\player-readiness\nMega3Audit.test.ts'),[Convert]::FromBase64String(''))
$Patch=@'
import fs from "node:fs";const f="package.json",p=JSON.parse(fs.readFileSync(f,"utf8"));p.scripts??={};p.scripts["audit:player-system:n-mega3"]="node scripts/n-mega3-2024-builder-progression-audit.mjs";p.scripts["test:n-mega3"]="vitest run src/certification/player-readiness/nMega3Audit.test.ts src/core/rulesets/originRules.test.ts src/core/rulesets/levelOneOriginReadiness.test.ts src/core/rulesets/featCatalog2024Official.test.ts src/core/rulesets/weaponMasteryRuntimeRules.test.ts src/core/rulesets/equipmentRules.test.ts src/core/rulesets/martialOfficialProgression.test.ts src/core/rulesets/halfCasterOfficialProgression.test.ts src/core/rulesets/clericDruidOfficialProgression.test.ts src/core/rulesets/bardSorcererOfficialProgression.test.ts src/core/rulesets/warlockWizardOfficialProgression.test.ts src/core/rulesets/spellBuilderOfficial.test.ts src/core/rulesets/spellRuntimeOfficial2024.test.ts src/core/rulesets/singleClassBuilderFinalCertification.integration.test.ts src/core/rulesets/highLevelAbilityBuilder.test.ts";p.scripts["certify:n-mega3"]="npm run audit:player-system:n-mega3 && npm run test:n-mega3 && npm run build";fs.writeFileSync(f,JSON.stringify(p,null,2)+"\n");
'@
$tmp=Join-Path $env:TEMP 'e4-nmega3-patch.mjs';Set-Content $tmp $Patch -Encoding UTF8;node $tmp;Remove-Item $tmp -Force
if(Test-Path (Join-Path $Root 'patch')){Remove-Item (Join-Path $Root 'patch') -Recurse -Force}
if(Test-Path (Join-Path $Root 'payload')){Remove-Item (Join-Path $Root 'payload') -Recurse -Force}
Write-Host 'N-MEGA3 audit + geniş regression + build çalıştırılıyor...' -ForegroundColor Yellow
npm.cmd run certify:n-mega3
if($LASTEXITCODE-ne 0){throw 'N-MEGA3 sertifikasyonu başarısız oldu. Terminal çıktısını gönderin.'}
Write-Host 'N-MEGA3 GREEN' -ForegroundColor Green
Write-Host 'Rapor: certification-reports\n-mega3\N_MEGA3_SUMMARY.md'
